      "seccion": "MD-L000019-L000026"
    },
    {
      "cita_literal_breve": "La revisión de proveedores atiende a vulnerabilidades específicas, calidad general, prácticas de ciberseguridad y desarrollo seguro, además de las evaluaciones coordinadas pertinentes.",
      "documento": "CYB-03",
      "fragmentos": [0],
      "seccion": "MD-L000019-L000026"
    },
    {
      "cita_literal_breve": "Si se constata incumplimiento de las medidas previstas, procede adoptar medidas correctoras apropiadas y proporcionadas sin demora indebida.",
